// Агрегация продаж + детект падения. Ожидаем массив сделок: {manager, amount, date}
const rows = $input.first().json;
const list = Array.isArray(rows) ? rows : rows.items || [];
const today = new Date().toISOString().slice(0, 10);
const byManager = {};
let totalToday = 0, totalYesterday = 0;
for (const r of list) {
  const m = r.manager || '(неизвестно)';
  const a = Number(r.amount) || 0;
  byManager[m] = (byManager[m] || 0) + a;
  if (r.date === today) totalToday += a; else totalYesterday += a;
}
const top5 = Object.entries(byManager)
  .sort((x, y) => y[1] - x[1]).slice(0, 5)
  .map(([m, s], i) => `${i + 1}. ${m}: ${s.toLocaleString('ru-RU')} ₽`);
const dropPct = totalYesterday > 0
  ? Math.round((totalYesterday - totalToday) / totalYesterday * 100)
  : 0;
const fallback = Number($input.first().json.fallback_total || 0);
if (list.length === 0 && fallback > 0) { totalToday = fallback; }
return [{ json: {
  totalToday,
  totalYesterday,
  dropPct,
  is_drop: totalYesterday > 0 && dropPct >= 10,
  top5_text: top5.join('\n') || '(нет сделок)',
  total_fmt: totalToday.toLocaleString('ru-RU') + ' ₽',
  yesterday_fmt: totalYesterday.toLocaleString('ru-RU') + ' ₽'
}}];

